```typescript
@Injectable({ providedIn: 'root' })
export class AiService {
  private readonly base = '/api/text';
  constructor(private http: HttpClient) {}

  brainstorm(text: string, question?: string, context?: string): Promise<TextResponse> {
    return this.post('brainstorm', { text, question, context });
  }
  expand(text: string)   { return this.post('expand', { text }); }
  compress(text: string) { return this.post('compress', { text }); }
  clarify(text: string)  { return this.post('clarify', { text }); }
  simplify(text: string) { return this.post('simplify', { text }); }
  tldr(text: string)     { return this.post('tldr', { text }); }
  bullets(text: string)  { return this.post('bullets', { text }); }
  rewrite(text: string, style: string) { return this.post('rewrite', { text, style }); }

  private post(action: string, body: object): Promise<TextResponse> {
    return firstValueFrom(
      this.http.post<TextResponse>(`${this.base}/${action}`, body)
        .pipe(timeout(AI_TIMEOUT_MS))
    );
  }
}
```

